&lt;div class=&quot;flex-col gap-1 md:gap-3&quot;&gt;
&lt;div class=&quot;flex max-w-full flex-col flex-grow&quot;&gt;
&lt;div class=&quot;min-h-[20px] text-message flex w-full flex-col items-end gap-2 whitespace-normal break-words [.text-message+&amp;amp;]:mt-5&quot; data-message-author-role=&quot;assistant&quot; data-message-id=&quot;266e3a10-dc9a-4829-b84e-6cf8d3c0f2e0&quot;&gt;
